{
  "tasks": [
    {
      "task_id": "T1",
      "title": "已完成订单城市销售额总和升序排名",
      "business_question": "按城市汇总已完成订单的销售额总和，并按销售额升序排列。仅看已完成订单。",
      "priority": "P0",
      "priority_reason": "直接回答核心分析目标“按城市汇总已完成订单的销售额总和，并按销售额升序排列”。删除此任务将无法获得任何业务结果。",
      "requirement_ids": [
        "C01",
        "C02",
        "C03",
        "C04"
      ],
      "depends_on": [],
      "missing_inputs": [],
      "steps": [
        {
          "step_id": "S1",
          "operation": "filter",
          "params": {
            "conditions": [
              {
                "field": "field_0004",
                "operator": "eq",
                "value": "已完成"
              }
            ]
          }
        },
        {
          "step_id": "S2",
          "operation": "group_aggregate",
          "params": {
            "metrics": [
              {
                "function": "sum",
                "field": "field_0005",
                "alias": "total_sales_amount"
              }
            ],
            "dimensions": [
              "field_0003"
            ]
          }
        },
        {
          "step_id": "S3",
          "operation": "sort",
          "params": {
            "field": "total_sales_amount",
            "direction": "asc"
          }
        }
      ]
    }
  ]
}
